import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        int[] poly = new int[10];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            poly[Integer.parseInt(st.nextToken())] = 1;
        }

        int[] ans = new int[]{1};
        int exp = n / 2;

        while (exp > 0) {
            if ((exp & 1) == 1) {
                ans = polyMul(ans, poly, 998244353);
            }
            poly = polyMul(poly, poly, 998244353);
            exp >>= 1;
        }

        long res = 0;
        for (int v : ans) {
            res = (res + (long)v * v) % 998244353;
        }
        System.out.println(res);
    }

    static int[] polyMul(int[] a, int[] b, int mod) {
        int need = a.length + b.length - 1;
        int size = Math.max(2, Integer.highestOneBit(need - 1) << 1);

        double[] ar = new double[size];
        double[] ai = new double[size];
        for (int i = 0; i < a.length; i++) {
            long x = a[i];
            x = ((x % mod) + mod) % mod;
            ar[i] = x & 32767;
            ai[i] = x >> 15;
        }
        fft(ar, ai, false);

        double[] br = new double[size];
        double[] bi = new double[size];
        for (int i = 0; i < b.length; i++) {
            long x = b[i];
            x = ((x % mod) + mod) % mod;
            br[i] = x & 32767;
            bi[i] = x >> 15;
        }
        fft(br, bi, false);

        double[] resr = new double[size];
        double[] resi = new double[size];
        double[] resj = new double[size];
        double[] resk = new double[size];

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double a1r = (ar[i] + ar[j]) * 0.5;
            double a1i = (ai[i] - ai[j]) * 0.5;
            double a2r = (ai[i] + ai[j]) * 0.5;
            double a2i = (ar[j] - ar[i]) * 0.5;

            double b1r = (br[i] + br[j]) * 0.5;
            double b1i = (bi[i] - bi[j]) * 0.5;
            double b2r = (bi[i] + bi[j]) * 0.5;
            double b2i = (br[j] - br[i]) * 0.5;

            resr[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resi[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            resj[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            resk[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(resr, resi, true);
        fft(resj, resk, true);

        int[] res = new int[need];
        for (int i = 0; i < need; i++) {
            long a = Math.round(resr[i]);
            long b = Math.round(resj[i]);
            long c = Math.round(resi[i]);
            res[i] = (int)((a + ((b % mod) << 15) + ((c % mod) << 30)) % mod);
        }
        return res;
    }

    static void fft(double[] re, double[] im, boolean inv) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; (j ^= bit) < bit; bit >>= 1);
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int h = 2; h <= n; h <<= 1) {
            double ang = 2 * Math.PI / h * (inv ? -1 : 1);
            double wr = Math.cos(ang);
            double wi = Math.sin(ang);

            for (int i = 0; i < n; i += h) {
                double w_r = 1.0;
                double w_i = 0.0;
                int half = h >> 1;
                for (int j = 0; j < half; j++) {
                    double ur = re[i + j];
                    double ui = im[i + j];
                    double vr = re[i + j + half] * w_r - im[i + j + half] * w_i;
                    double vi = re[i + j + half] * w_i + im[i + j + half] * w_r;

                    re[i + j] = ur + vr;
                    im[i + j] = ui + vi;
                    re[i + j + half] = ur - vr;
                    im[i + j + half] = ui - vi;

                    double t = w_r * wr - w_i * wi;
                    w_i = w_r * wi + w_i * wr;
                    w_r = t;
                }
            }
        }

        if (inv) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }
}
